insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',0,'dua','Morning gratitude','أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',1,'quran','Ayat ul Kursi',null,null,null,null,1,2,255,255);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',2,'quran','Surah Ikhlas',null,null,null,null,3,112,1,4);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',3,'quran','Surah Falaq',null,null,null,null,3,113,1,5);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',4,'quran','Surah Nas',null,null,null,null,3,114,1,6);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',5,'dua','Infinite Praiser','سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ','Glory is to Allah and praise is to Him by the number of His creation, by His pleasure, by the weight of His Throne, and by the ink of His words.','Subhanallahi wa bihamdihi adada khalqihi wa rida nafsihi wa zinata arshihi wa midada kalimatihi',null,3,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',6,'dua','Morning Reliance','اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ','O Allah, by You we enter the morning, and by You we enter the evening, by You we live, and by You we die, and to You is the resurrection.','Allahumma bika asbahna wa bika amsayna wa bika nahya wa bika namut wa ilaykan-nushoor',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',7,'dua','Affirmation of Faith','أَصْبَحْنَا عَلَىٰ فِطْرَةِ الإِسْلَامِ، وَكَلِمَةِ الإِخْلاَصِ، وَعَلَىٰ دِينِ نَبِيِّنَا مُحَمَّدٍ ﷺ، وَعَلَىٰ مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ','We have entered the morning upon the natural religion of Islam, the word of sincere devotion (Shahadah), the religion of our Prophet Muhammad ﷺ, and the way of our father Abraham, who was upright and a Muslim, and was not of those who associate others with Allah.','Asbahna ala fitratil-Islam wa kalimatil-ikhlas wa ala dini nabiyyina Muhammad sallallahu alayhi wa sallam wa ala millati abina Ibrahim hanifan Musliman wa ma kana min al-mushrikeen',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',8,'dua','Tawheed and Protection','اللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، لَا إِلَهَ إِلَّا أَنْتَ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَىٰ نَفْسِي سُوءًا، أَوْ أَجُرَّهُ إِلَىٰ مُسْلِمٍ','O Allah Creator of the heavens and the earth Knower of the unseen and the seen there is no god but You Lord and Owner of everything I seek refuge in You from the evil of myself from the evil of Shaytan and his traps and from bringing harm upon myself or dragging it onto another Muslim','Allahumma fatiras samawati wal ard ʿalimal ghaybi wash shahadah la ilaha illa anta rabbakulli shay’in wa malikahu aʿudhu bika min sharri nafsi wa min sharri ash shaytani wa shirkih wa an aqtarifa ʿala nafsi su’an aw ajurrahu ila muslim',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',9,'dua','Dua for Contentment','رَضِيتُ بِاللّٰهِ رَبًّا وَبِالْإِسْلَامِ دِينًا وَبِمُحَمَّدٍ ﷺ نَبِيًّا','I am pleased with Allah as my Lord, Islam as my religion, and Muhammad ﷺ as my Prophet.','Raditu billahi rabban wa bil-islami dinan wa bi-Muhammadin nabiyyan',null,3,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',10,'dua','Protection Dua','بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ','In the name of Allah with whose name nothing on earth or in the heavens can cause harm, and He is the All-Hearing, All-Knowing','Bismillahil-ladhi la yadurru maasmihi shay''un fil-ardi wa la fis-sama''i wa huwa as-sami''ul alim',null,3,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',11,'dua','Wellbeing & Health','اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ','O Allah, grant well-being to my body. O Allah, grant well-being to my hearing. O Allah, grant well-being to my sight. There is no deity but You.','Allahumma aafini fi badani Allahumma aafini fi sam''i Allahumma aafini fi basari la ilaha illa anta',null,3,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',12,'dua','Dua for Forgiveness','اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ','O Allah, I seek refuge in You from disbelief and poverty, and I seek refuge in You from the punishment of the grave. There is no deity except You.','Allahumma inni a''udhu bika minal-kufri wal-faqr wa a''udhu bika min adhabil-qabr la ilaha illa anta',null,3,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',13,'dua','Total dependence on Allah','يَا حَيُّ يَا قَيُّومُ، بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلَا تَكِلْنِي إِلَىٰ نَفْسِي طَرْفَةَ عَيْنٍ','O Ever-Living, O Sustainer, by Your mercy I seek help, rectify for me all of my affairs, and do not leave me to myself even for the blink of an eye.','Ya Hayyu ya Qayyum birahmatika astagheeth aslih li sha''ni kullah wa la takilni ila nafsi tarfata ayn',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',14,'dua','Sayyid ul Astaghfar','اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَٰهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَىٰ عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ','O Allah, You are my Lord. There is no god but You. You created me and I am Your servant, and I abide to Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I admit to You Your blessings upon me, and I admit to You my sins, so forgive me, for surely no one forgives sins except You.','Allahumma anta rabbi la ilaha illa anta khalaqtani wa ana abduk wa ana ala ahdika wa wa''dika ma ista''ta''t a''udhu bika min sharri ma sana''t aboo''u laka bini''matika alayya wa aboo''u bidhanbi faghfir li fa innahu la yaghfiru adh-dhunuba illa anta',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',15,'dua','Protection from harm','اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي، وَعَنْ يَمِينِي وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي','O Allah I ask You for well-being in this world and the Hereafter O Allah I ask You for forgiveness and well-being in my religious and worldly affairs and my family and my wealth O Allah conceal my faults and calm my fears O Allah protect me from in front of me and from behind me and from my right and from my left and from above me and I seek refuge in Your greatness from being taken unaware from beneath me','Allahumma inni as’aluka al-afiyah fid-dunya wal-akhirah Allahumma inni as’aluka al-afwa wal-afiyah fi dini wa dunyaya wa ahli wa mali Allahumma astur ‘awrati wa amin raw‘ati Allahumma ihfazni min bayni yadayya wa min khalfī wa ‘an yamini wa ‘an shimali wa min fawqi wa a‘udhu bi ‘azamatika an ughtala min tahti',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',16,'dua','Remembrance','لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ','There is no god but Allah alone, without partner. To Him belongs the dominion, and to Him belongs all praise, and He is over all things capable.','La ilaha illallahu wahdahu la sharika lah lahul mulku wa lahul hamdu wa huwa ala kulli shay''in qadir',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',17,'dua','Lightest yet Heaviest','سُبْحَانَ اللَّهِ وَبِحَمْدِهِ','Glory is to Allah and praise is to Him','Subhanallahi wa bihamdihi',null,100,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('morning',18,'dua','Dhikr: Astaghfirullah','أَسْتَغْفِرُ اللَّهَ','I seek forgiveness from Allah','Astaghfirullāh',null,100,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',0,'dua','Evening gratitude','اللَّهُمَّ أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',1,'quran','Ayat ul Kursi',null,null,null,null,1,2,255,255);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',2,'dua','Evening Reliance','اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ الْمَصِيرُ','O Allah, by Your leave we have reached the evening and by Your leave we reach the morning. By Your leave we live and by Your leave we die. And to You is the return.','Allahumma bika amsayna wa bika asbahna wa bika nahya wa bika namut wa ilaykal maseer.',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',3,'dua','Affirmation of Faith','أَمْسَيْنَا عَلَىٰ فِطْرَةِ الإِسْلَامِ، وَكَلِمَةِ الإِخْلَاصِ، وَعَلَىٰ دِينِ نَبِيِّنَا مُحَمَّدٍ ﷺ، وَعَلَىٰ مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ','We have entered the evening upon the natural religion of Islam, and the word of sincere devotion, and upon the religion of our Prophet Muhammad ﷺ, and the way of our forefather Ibrahim, who was upright and a Muslim, and was not among the polytheists.','Amsayna ala fitratil Islam wa kalimatil ikhlas wa ala deeni nabiyyina Muhammadin sallallahu alayhi wa sallam wa ala millati abina Ibrahima hanifan musliman wa ma kana minal mushrikeen.',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',4,'dua','Tawheed and Protection','اللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، لَا إِلَهَ إِلَّا أَنْتَ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَىٰ نَفْسِي سُوءًا، أَوْ أَجُرَّهُ إِلَىٰ مُسْلِمٍ','O Allah Creator of the heavens and the earth Knower of the unseen and the seen there is no god but You Lord and Owner of everything I seek refuge in You from the evil of myself from the evil of Shaytan and his traps and from bringing harm upon myself or dragging it onto another Muslim','Allahumma fatiras samawati wal ard ʿalimal ghaybi wash shahadah la ilaha illa anta rabbakulli shay’in wa malikahu aʿudhu bika min sharri nafsi wa min sharri ash shaytani wa shirkih wa an aqtarifa ʿala nafsi su’an aw ajurrahu ila muslim',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',5,'dua','Protection Dua','بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ','In the name of Allah with whose name nothing on earth or in the heavens can cause harm, and He is the All-Hearing, All-Knowing','Bismillahil-ladhi la yadurru maasmihi shay''un fil-ardi wa la fis-sama''i wa huwa as-sami''ul alim',null,3,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',6,'dua','Dua for Forgiveness','اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ','O Allah, I seek refuge in You from disbelief and poverty, and I seek refuge in You from the punishment of the grave. There is no deity except You.','Allahumma inni a''udhu bika minal-kufri wal-faqr wa a''udhu bika min adhabil-qabr la ilaha illa anta',null,3,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',7,'dua','Evening Protection Duʿa','أَعُوذُ بِكَلِمَاتِ اللّٰهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ','I seek refuge in the perfect words of Allah from the evil of what He has created.','A''udhu bikalimatillahi tammati min sharri ma khalaq.',null,3,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',8,'dua','Wellbeing & Health','اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ','O Allah, grant well-being to my body. O Allah, grant well-being to my hearing. O Allah, grant well-being to my sight. There is no deity but You.','Allahumma aafini fi badani Allahumma aafini fi sam''i Allahumma aafini fi basari la ilaha illa anta',null,3,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',9,'dua','Total dependence on Allah','يَا حَيُّ يَا قَيُّومُ، بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلَا تَكِلْنِي إِلَىٰ نَفْسِي طَرْفَةَ عَيْنٍ','O Ever-Living, O Sustainer, by Your mercy I seek help, rectify for me all of my affairs, and do not leave me to myself even for the blink of an eye.','Ya Hayyu ya Qayyum birahmatika astagheeth aslih li sha''ni kullah wa la takilni ila nafsi tarfata ayn',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',10,'dua','Sayyid ul Astaghfar','اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَٰهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَىٰ عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ','O Allah, You are my Lord. There is no god but You. You created me and I am Your servant, and I abide to Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I admit to You Your blessings upon me, and I admit to You my sins, so forgive me, for surely no one forgives sins except You.','Allahumma anta rabbi la ilaha illa anta khalaqtani wa ana abduk wa ana ala ahdika wa wa''dika ma ista''ta''t a''udhu bika min sharri ma sana''t aboo''u laka bini''matika alayya wa aboo''u bidhanbi faghfir li fa innahu la yaghfiru adh-dhunuba illa anta',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',11,'dua','Protection from harm','اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي، وَعَنْ يَمِينِي وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي','O Allah I ask You for well-being in this world and the Hereafter O Allah I ask You for forgiveness and well-being in my religious and worldly affairs and my family and my wealth O Allah conceal my faults and calm my fears O Allah protect me from in front of me and from behind me and from my right and from my left and from above me and I seek refuge in Your greatness from being taken unaware from beneath me','Allahumma inni as’aluka al-afiyah fid-dunya wal-akhirah Allahumma inni as’aluka al-afwa wal-afiyah fi dini wa dunyaya wa ahli wa mali Allahumma astur ‘awrati wa amin raw‘ati Allahumma ihfazni min bayni yadayya wa min khalfī wa ‘an yamini wa ‘an shimali wa min fawqi wa a‘udhu bi ‘azamatika an ughtala min tahti',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',12,'quran','Surah Ikhlas',null,null,null,null,3,112,1,4);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',13,'quran','Surah Falaq',null,null,null,null,3,113,1,5);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',14,'quran','Surah Nas',null,null,null,null,3,114,1,6);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',15,'dua','Remembrance','لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ','There is no god but Allah alone, without partner. To Him belongs the dominion, and to Him belongs all praise, and He is over all things capable.','La ilaha illallahu wahdahu la sharika lah lahul mulku wa lahul hamdu wa huwa ala kulli shay''in qadir',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',16,'dua','Lightest yet Heaviest','سُبْحَانَ اللَّهِ وَبِحَمْدِهِ','Glory is to Allah and praise is to Him','Subhanallahi wa bihamdihi',null,100,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('evening',17,'dua','Dhikr: Astaghfirullah','أَسْتَغْفِرُ اللَّهَ','I seek forgiveness from Allah','Astaghfirullāh',null,100,null,null,null);
