insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('night',1,'dua','Sleeping Dua','اللَّهُمَّ بِاسْمِكَ أَمُوتُ وَأَحْيَا','O Allah, in Your name I die and I live.','Allahumma bismika amootu wa ahya',null,1,null,null,null);
