insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('friday',0,'dua','Salawat','اللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ','O Allah, send blessings upon Muhammad','Allahumma salli ala Muhammad',null,1,null,null,null);
