insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('after_salah',6,'dua','Reflecting on peace','اللَّهُمَّ أَنْتَ السَّلَامُ، وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ','O Allah, You are Peace, and from You comes peace. Blessed are You, O Possessor of Majesty and Honor.','Allahumma anta as-salaamu wa minka as-salaam, tabaarakta yaa dhal-jalaali wal-ikraam',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('after_salah',7,'dua','Subhanallah','سُبْحَانَ اللَّهِ','Glory be to Allah','Subhanallah',null,33,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('after_salah',8,'dua','Alhamdulilah','الْـحَمْدُ لِلَّهِ','All praise is due to Allah','Alhamdulilah',null,33,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('after_salah',9,'dua','Allahu Akbar','اللَّهُ أَكْبَرُ','Allah is the greatest','Allahu Akbar',null,34,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('after_salah',10,'dua','Purification of tongue and heart','سُبْحَانَ اللَّهِ وَبِحَمْدِهِ','Glory is to Allah and all praise is to Him','Subḥānallāhi wa biḥamdih',null,100,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('after_salah',11,'dua','Remembrance','لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ','There is no god but Allah, alone, and He has no partner','Lā ilāha illallāhu waḥdahu lā sharīka lah',null,100,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('dua_before_sleeping',0,'dua','Dua before sleeping','اللَّهُمَّ بِاسْمِكَ أَمُوتُ وَأَحْيَا','O Allah, in Your name I die and I live.','Allahumma bismika amootu wa ahya',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('dua_after_waking_up',0,'dua','Dua after waking up','الْـحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ','All praise is for Allah who gave us life after causing us to die, and to Him is the resurrection.','Alhamdu lillahi alladhi ahyana ba’da ma amatana wa ilayhi an-nushoor',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('dua_when_entering_the_house',0,'dua','Dua when entering the house','بِسْمِ اللَّهِ وَلَجْنَا وَبِسْمِ اللَّهِ خَرَجْنَا وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا','In the name of Allah we enter, in the name of Allah we leave, and upon our Lord we place our trust.','Bismillahi walajna wa bismillahi kharajna wa alallahi rabbina tawakkalna',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('dua_when_exiting_the_house',0,'dua','Dua when exiting the house','بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ','In the name of Allah, I place my trust in Allah, and there is no power nor strength except with Allah.','Bismillahi tawakkaltu alallah wa la hawla wa la quwwata illa billah',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('dua_when_entering_the_bathroom',0,'dua','Dua when entering the bathroom','اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ','O Allah, I seek refuge with You from male and female devils.','Allahumma inni a’udhu bika minal khubuthi wal khabaith',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('dua_when_leaving_the_bathroom',0,'dua','Dua when leaving the bathroom','غُفْرَانَكَ','I seek Your forgiveness.','Ghufranaka',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_perform_dhikr_takbeer',0,'dua','Allahu Akbar, Allahu Akbar, Allahu…','اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، لا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، وَلِلَّهِ الْحَمْدُ','Allah is the Greatest, Allah is the Greatest, Allah is the Greatest. There is no god but Allah. And Allah is the Greatest, Allah is the Greatest, and to Allah belongs all praise.','Allahu Akbar, Allahu Akbar, Allahu Akbar, la ilaha illallah, wallahu Akbar, Allahu Akbar, wa lillahil hamd',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_perform_dhikr_takbeer',1,'dua','Allahummaghfir li wa aafini warzuqni','اللَّهُمَّ اغْفِرْ لِي، وَعَافِنِي، وَارْزُقْنِي','O Allah, forgive me, grant me wellbeing, and provide for me.','Allahummaghfir li wa aafini warzuqni',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_perform_dhikr_takbeer',2,'dua','Labbaika Allahumma labbaik, labbaika la…','لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ','Here I am, O Allah, here I am. Here I am, You have no partner, here I am. Surely, all praise, blessings, and sovereignty are Yours. You have no partner.','Labbaika Allahumma labbaik, labbaika la sharika laka labbaik, inna al-ḥamda wa ni‘mata laka wal-mulk, la sharika lak',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_perform_dhikr_takbeer',3,'quran','Al-Baqarah 2:152',null,null,null,null,1,2,152,152);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_perform_dhikr_takbeer',4,'quran','Al-Ahzab 33:41–42',null,null,null,null,1,33,41,42);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_perform_dhikr_takbeer',5,'quran','Al-Muzzammil 73:8',null,null,null,null,1,73,8,8);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_perform_dhikr_takbeer',6,'quran','Al-Hajj 22:28',null,null,null,null,1,22,28,28);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_do_istaghfar_thank_allah',0,'dua','Astaghfirullāh','أَسْتَغْفِرُ اللهَ','I seek Allah’s forgiveness.','Astaghfirullāh',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_do_istaghfar_thank_allah',1,'dua','Rabbi ighfir lī warḥamnī','رَبِّ اغْفِرْ لِي وَارْحَمْنِي','My Lord, forgive me and have mercy on me.','Rabbi ighfir lī warḥamnī',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_do_istaghfar_thank_allah',2,'dua','Allāhumma innī ẓalamtu nafsī ẓulman…','اَللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا','O Allah, I have wronged myself greatly.','Allāhumma innī ẓalamtu nafsī ẓulman kathīran',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_do_istaghfar_thank_allah',3,'dua','Al-ḥamdu lillāh','الْـحَمْدُ للهِ','All praise is due to Allah.','Al-ḥamdu lillāh',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_do_istaghfar_thank_allah',4,'dua','Allāhumma laka al-ḥamdu kamā yanbaghī…','اَللَّهُمَّ لَكَ الْحَمْدُ كَمَا يَنْبَغِي لِجَلاَلِ وَجْهِكَ وَعَظِيمِ سُلْطَانِكَ','O Allah, all praise is due to You as is befitting to Your Majesty and Great Authority.','Allāhumma laka al-ḥamdu kamā yanbaghī li-jalāli wajhika wa ʿaẓīmi sulṭānik',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_do_istaghfar_thank_allah',5,'dua','Rabbi ighfir lī wa tub ʿalayya innaka…','رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ','My Lord, forgive me and accept my repentance. You are the Accepter of repentance, the Merciful.','Rabbi ighfir lī wa tub ʿalayya innaka anta at-tawwābu ar-raḥīm',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_do_istaghfar_thank_allah',6,'dua','Rabbi ighfir lī wa li-wālidayya wa…','رَبِّ اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ','My Lord, forgive me, my parents, and the believers on the Day of Reckoning.','Rabbi ighfir lī wa li-wālidayya wa lil-muʾminīn yawma yaqūmu al-ḥisāb',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_do_istaghfar_thank_allah',7,'dua','Allāhumma ighfir lī dhanbī kullahu,…','اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ، دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلاَنِيَتَهُ وَسِرَّهُ','O Allah, forgive all my sins, the small and great, the first and last, the open and secret.','Allāhumma ighfir lī dhanbī kullahu, diqqahu wa jillahu, wa awwalahu wa ākhirahu, wa ʿalāniyatahu wa sirrahu',null,1,null,null,null);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_do_istaghfar_thank_allah',8,'quran','An-Naml 27:19',null,null,null,null,1,27,19,19);
insert into public.adhkar_items (set_key,sort,type,title,arabic,translation,transliteration,reference,repeat,surah,verse_from,verse_to) values ('zilhaj_do_istaghfar_thank_allah',9,'dua','Subḥānallāhi wa biḥamdihi ʿadada…','سُبْحَانَ اللهِ وَبِحَمْدِهِ عَدَدَ خَلْقِهِ وَرِضَا نَفْسِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ','Glory and praise be to Allah, as many times as the number of His creations, His pleasure, the weight of His throne, and the ink of His words.','Subḥānallāhi wa biḥamdihi ʿadada khalqihi wa riḍā nafsihi wa zinata ʿarshihi wa midāda kalimātihi',null,1,null,null,null);
