insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Actions are judged by intentions."','Bukhari 1',false,0);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"A Muslim is one who avoids harming others with his tongue and hands."','Bukhari 10',false,1);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"None of you believes until he loves for his brother what he loves for himself."','Bukhari 13',false,2);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Make things easy, not difficult; give glad tidings, not discouragement."','Bukhari 69',false,3);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The strong person is not one who can wrestle, but one who controls his anger."','Bukhari 6114',false,4);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Whoever believes in Allah and the Last Day should speak good or stay silent."','Bukhari 6018',false,5);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Feed the hungry, visit the sick, and free the captives."','Bukhari 5649',false,6);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The believer is not one who eats while his neighbor goes hungry."','Bukhari 6017',false,7);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Be kind to others and you will receive kindness."','Muslim 2699',false,8);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Allah loves gentleness in all matters."','Bukhari 6927',false,9);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The best people are those who benefit others most."','Bukhari 2442',false,10);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Paradise lies under the feet of your mother."','Ahmad 3/429',false,11);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Every good deed is charity."','Muslim 1005',false,12);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The upper hand is better than the lower hand."','Bukhari 1429',false,13);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Modesty brings only good."','Bukhari 6117',false,14);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Allah does not look at your bodies but at your hearts and deeds."','Muslim 2564',false,15);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Help your brother whether he wrongs or is wronged."','Bukhari 2444',false,16);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The most beloved deed to Allah is the most regular one."','Bukhari 6465',false,17);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Whoever is not kind to people, Allah will not be kind to him."','Bukhari 7376',false,18);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"All of Adam''s children make mistakes; the best are those who repent."','Tirmidhi 2499',false,19);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Be merciful and you will receive mercy."','Ahmad 7001',false,20);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The journey to seek knowledge is a path to Paradise."','Tirmidhi 2646',false,21);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Every disease has a cure except death."','Bukhari 5678',false,22);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The world is green and beautiful; Allah made you its guardians."','Muslim 2742',false,23);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Whoever thanks people has thanked Allah."','Tirmidhi 1954',false,24);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"What is lawful is clear and what is unlawful is clear."','Bukhari 52',false,25);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Worship Allah as if you see Him; if not, know that He sees you."','Bukhari 50',false,26);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The believers are like one body in their love and mercy."','Bukhari 6011',false,27);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Whoever hides a Muslim''s fault, Allah will hide his faults."','Muslim 2699',false,28);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The best believer is one with the best character."','Tirmidhi 1162',false,29);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"When one of you does work, Allah loves that he does it well."','Tabarani 891',false,30);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The best companions remind you of Allah when you see them."','Tirmidhi 2395',false,31);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"No one believes until he wants for others what he wants for himself."','Bukhari 13',false,32);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The best people live longest and do the best deeds."','Tirmidhi 2329',false,33);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Whoever removes someone''s worry, Allah will remove his worry."','Muslim 2699',false,34);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"A kind word is charity."','Bukhari 2989',false,35);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The most perfect believers have the best manners."','Abu Dawud 4682',false,36);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Be kind to animals; there is reward in serving any living being."','Bukhari 2466',false,37);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The best jihad is speaking truth to an unjust ruler."','Abu Dawud 4344',false,38);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Kindness is a sign of faith; whoever lacks kindness lacks faith."','Muslim 54',false,39);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Visit the sick, feed the hungry, and help the troubled."','Bukhari 5649',false,40);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The reward of good deeds depends on the intentions behind them."','Bukhari 1',false,41);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Make it easy for people and do not make it hard for them."','Bukhari 220',false,42);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Whoever wishes to be kept away from Hell and enter Paradise should treat people as they want to be treated."','Muslim 1844',false,43);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The best of you are those who learn the Quran and teach it."','Bukhari 5027',false,44);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"A man walking along a path felt very thirsty and found a well, so he climbed down and drank. When he came up, he saw a dog panting from thirst, so he went back down and brought water for the dog. Allah thanked him and forgave his sins."','Bukhari 2466',false,45);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Do not wish to be like anyone except in two cases: a man whom Allah has given wealth and he spends it righteously, and a man whom Allah has given wisdom and he acts and teaches it."','Bukhari 73',false,46);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The person who goes to bed full while his neighbor is hungry is not one of us."','Tabarani 8720',false,47);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Whoever says ''There is no god but Allah'' will enter Paradise."','Bukhari 5827',false,48);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The best houses are those where orphans are well treated."','Ibn Majah 3679',false,49);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Allah will not show mercy to him who does not show mercy to others."','Bukhari 7376',false,50);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"A prostitute was forgiven by Allah because she gave water to a thirsty dog."','Bukhari 3467',false,51);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The most beloved places to Allah are the mosques."','Muslim 671',false,52);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Do not get angry and Paradise will be yours."','Bukhari 6116',false,53);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The best wealth is a tongue that remembers Allah."','Tirmidhi 3375',false,54);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Whoever relieves a Muslim of a burden from the burdens of the world, Allah will relieve him of a burden from the burdens of the Hereafter."','Muslim 2699',false,55);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The believer who mixes with people and bears their annoyance with patience will have a greater reward than the believer who does not mix with people."','Ibn Majah 4032',false,56);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Every act of kindness is charity."','Bukhari 2989',false,57);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"He who sleeps on a full stomach while his neighbor goes hungry is not one of us."','Hakim 7939',false,58);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"A good leader is one who when people see him, they remember Allah."','Tirmidhi 2325',false,59);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Keep your duty to Allah wherever you are."','Tirmidhi 1987',false,60);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"No one has eaten better food than that which he has eaten out of the work of his hand."','Bukhari 2072',false,61);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"Allah has appointed a guardian for every person."','Bukhari 6502',false,62);
insert into public.daily_items (kind,text,reference,verified,sort) values ('hadith','"The best prayer after the obligatory prayers is the night prayer."','Muslim 1163',false,63);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','The Prophet ﷺ said: "Your smile for your brother is a charity."','Tirmidhi 1956',false,64);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"The best among you are those who have the best manners."','Bukhari 3559',false,65);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Make things easy, not difficult; give glad tidings, not discouragement."','Bukhari 69',false,66);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"He who does not thank people, does not thank Allah."','Tirmidhi 1954',false,67);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"True strength is in self-control, not overpowering others."','Bukhari 6114',false,68);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Exchange gifts, as that will lead to increasing your love to one another."','Bukhari 2567',false,69);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"The most beloved deeds to Allah are those done consistently, even if small."','Bukhari 6465',false,70);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"You truly believe when you love for your brother what you love for yourself."','Bukhari 13',false,71);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Feed the hungry, visit the sick, and free the captive."','Bukhari 5649',false,72);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"The best among you are those who learn the Quran and teach it."','Bukhari 5027',false,73);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Shake hands—it removes hatred and strengthens brotherhood."','Muwatta Malik 1746',false,74);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Say Salam to those you know and those you don''t."','Bukhari 6236',false,75);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Use the miswak, for it cleanses the mouth and pleases the Lord."','Bukhari 887',false,76);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Eat with your right hand and say Bismillah."','Bukhari 5376',false,77);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Do not waste water, even if by a flowing river."','Ibn Majah 425',false,78);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Help your brother, whether he is an oppressor or oppressed."','Bukhari 2444',false,79);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Speak good; if you cannot then remain silent."','Bukhari 6018',false,80);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','A man asked the Prophet ﷺ for advice. He said: "Do not get angry."','Bukhari 6116',false,81);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Secure your means; tie your camel then trust in Allah."','Tirmidhi 2517',false,82);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Visit the sick—it softens the heart and earns Allah’s mercy."','Muslim 2199',false,83);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Cover your mouth when yawning, as it is from Shaytan."','Bukhari 6226',false,84);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','The Prophet ﷺ said: "Do not lie, even if you are joking."','Tirmidhi 1995',false,85);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Supplicate sincerely and believe it will be answered."','Tirmidhi 3479',false,86);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Recite Ayat al-Kursi before sleeping for Allah’s protection."','Bukhari 2311',false,87);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','The Prophet ﷺ said: "Sleep on your right side for blessings."','Bukhari 6312',false,88);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"The Prophet ﷺ sought Allah’s forgiveness over 70 times daily."','Bukhari 6307',false,89);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"The Prophet ﷺ urged kindness to neighbors."','Muslim 2625',false,90);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Give charity, even if it is half a date. Charity protects from the Hellfire."','Bukhari 1410',false,91);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Gentleness brings blessings; harshness removes them."','Muslim 2594',false,92);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Say Salam before speaking—it''s the right of a Muslim."','Tirmidhi 2699',false,93);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Visit graves—they remind you of the Hereafter."','Muslim 976',false,94);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"The Prophet ﷺ avoided eating while reclining, as it''s a sign of pride."','Bukhari 5398',false,95);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Two rak''ahs before Fajr are better than the world and all in it."','Bukhari 1116',false,96);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"After sneezing, say ''Alhamdulillah''—a praised Sunnah."','Bukhari 6224',false,97);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Avoid suspicion, for it is the worst of false tales."','Bukhari 6066',false,98);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Use the right hand for eating and drinking."','Muslim 2020',false,99);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Say ''Bismillah'' before entering the home."','Muslim 2018',false,100);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"The Prophet ﷺ encouraged grooming of hair and appearing neat."','Abu Dawood 4163',false,101);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"He is not of us who shows no mercy to children."','Bukhari 5997',false,102);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Respecting elders shows reverence for Allah."','Tirmidhi 2022',false,103);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Lower your gaze—it purifies the heart and guards modesty."','Muslim 2159',false,104);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"No one with pride equal to a mustard seed enters Paradise."','Muslim 91',false,105);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Say Salam when entering your home; it brings blessings."','Nur 24:61',false,106);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Make dua for others in their absence, and angels will pray the same for you."','Muslim 2732',false,107);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Do not interrupt others while they speak."','Bukhari 2690',false,108);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Eat from what is nearest to you and observe table manners."','Muslim 2022',false,109);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Walk humbly—the believers are those who walk gently."','Furqan 25:63',false,110);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Avoid backbiting—it''s like eating your dead brother''s flesh."','Hujurat 49:12',false,111);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Be honest in trade—the truthful will be with the prophets."','Bukhari 2076',false,112);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Start with the right when putting on shoes."','Bukhari 168',false,113);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Show gratitude for even small favors."','Tirmidhi 1954',false,114);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"The Prophet ﷺ visited the poor and sat among them."','Ibn Majah 4129',false,115);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Say ''La ilaha illallah'' often—it renews faith."','Ahmad 8497',false,116);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Do not belittle any good deed, even a smile."','Muslim 2626',false,117);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Maintain family ties, even with those who cut you off."','Bukhari 5988',false,118);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Begin tasks with Bismillah—it brings blessings."','Ibn Majah 3264',false,119);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Pray Tahajjud—it draws you nearer to Allah."','Muslim 1163',false,120);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Say ''Astaghfirullah'' often—it opens doors of mercy."','Bukhari 6307',false,121);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Sit where you find space, not by status."','Abu Dawood 482',false,122);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Whenever you are wronged, forgive—it elevates you."','Bukhari 5678',false,123);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Feed your servant from what you eat and clothe them as yourself."','Muslim 1661',false,124);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Speak gently, even when correcting others."','Bukhari 6030',false,125);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Be punctual with salah—it is the pillar of Islam."','Bukhari 553',false,126);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Giving water is among the best forms of charity in Islam."','Abu Dawood 1670',false,127);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Do not curse time, for Allah controls it."','Bukhari 4826',false,128);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Say Salam when leaving, as when entering."','Tirmidhi 2706',false,129);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"The Prophet ﷺ encouraged going to bed in a state of wudu (ablution)."','Bukhari 247',false,130);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Saying ''Bismillah'' before undressing serves as a shield from jinn."','Tirmidhi 606',false,131);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Reconciling people is more virtuous than prayer, fasting, and charity."','Abu Dawood 4919',false,132);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Whoever builds a masjid, Allah will build for him a house in Jannah."','Muslim 533',false,133);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Remember death often—it destroys worldly desires."','Tirmidhi 2307',false,134);
insert into public.daily_items (kind,text,reference,verified,sort) values ('sunnah','"Be just—even if it is against yourself or those closest to you."','An-Nisa 4:135',false,135);
